-- Exclusivamente banco local; IDs reservados às fixtures deste teste.
begin;
create extension if not exists dblink with schema extensions;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public;
select plan(32);
select extensions.dblink_connect_u('s165a', 'dbname=postgres user=supabase_admin');
select extensions.dblink_connect_u('s165b', 'dbname=postgres user=supabase_admin');
select extensions.dblink_exec('s165a', $$
 set app.auvo_sync_write = 'true';
 insert into auth.users(id, instance_id, aud, role, email, encrypted_password, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
 values ('16590000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 's165-concorrencia@test.local', crypt('x', gen_salt('bf')), '{}', '{}', now(), now());
 insert into config.usuarios(user_id, papel, nome, ativo) values ('16590000-0000-0000-0000-000000000001', 'superadmin', 'Teste S165', true);
 insert into pcm.clientes(id, nome, ativo, created_by) values ('16590000-0000-0000-0000-00000000000a', 'Cliente teste S165', true, '16590000-0000-0000-0000-000000000001');
 insert into config.sso_concessoes(usuario_id, acao, cliente_id) values ('16590000-0000-0000-0000-000000000001', 'plano.gerir', '16590000-0000-0000-0000-00000000000a');
 insert into pcm.sistemas(id, cliente_id, nome) values ('16590000-0000-0000-0000-000000000051', '16590000-0000-0000-0000-00000000000a', 'Sistema teste S165');
 set request.jwt.claims = '{"sub":"16590000-0000-0000-0000-000000000001","role":"authenticated","user_role":"superadmin"}';
 set role authenticated;
 do $fixture$ begin
 perform pcm.sso_salvar_plano_rascunho('16590000-0000-0000-0000-000000000101', 0, '16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-00000000000a', 'Plano teste S165');
 perform pcm.sso_adicionar_rotina_rascunho('16590000-0000-0000-0000-000000000102', 1, '16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-000000000081', 'Rotina teste', 'sistema', '16590000-0000-0000-0000-000000000051', 'calendario', 1, 'meses', null, 0);
 perform pcm.sso_salvar_plano_rascunho('16590000-0000-0000-0000-000000000111', 0, '16590000-0000-0000-0000-000000000012', '16590000-0000-0000-0000-00000000000a', 'Plano revisão primeiro');
 perform pcm.sso_adicionar_rotina_rascunho('16590000-0000-0000-0000-000000000112', 1, '16590000-0000-0000-0000-000000000012', '16590000-0000-0000-0000-000000000082', 'Rotina revisão primeiro', 'sistema', '16590000-0000-0000-0000-000000000051', 'calendario', 1, 'meses', null, 0);
 perform pcm.sso_salvar_plano_rascunho('16590000-0000-0000-0000-000000000121', 0, '16590000-0000-0000-0000-000000000013', '16590000-0000-0000-0000-00000000000a', 'Plano retirada primeiro');
 perform pcm.sso_adicionar_rotina_rascunho('16590000-0000-0000-0000-000000000122', 1, '16590000-0000-0000-0000-000000000013', '16590000-0000-0000-0000-000000000083', 'Rotina retirada primeiro', 'sistema', '16590000-0000-0000-0000-000000000051', 'calendario', 1, 'meses', null, 0);
 end $fixture$;
$$);
select extensions.dblink_exec('s165b', $$ set request.jwt.claims = '{"sub":"16590000-0000-0000-0000-000000000001","role":"authenticated","user_role":"superadmin"}' $$);
select extensions.dblink_exec('s165b', 'set role authenticated');
-- Submissão confirmada impede retirada baseada no rascunho anterior.
select extensions.dblink_exec('s165a', 'begin');
select extensions.dblink_exec('s165b', 'begin');
select is(resultado->>'state', 'em_revisao', 'submissão inicia transição') from extensions.dblink('s165a', $$ select pcm.sso_transicionar_revisao_plano('16590000-0000-0000-0000-000000000113', 2, '16590000-0000-0000-0000-000000000012', 'submeter') $$) as t(resultado jsonb);
select is(extensions.dblink_send_query('s165b', $$ select pcm.sso_retirar_rotina_rascunho('16590000-0000-0000-0000-000000000114', 2, '16590000-0000-0000-0000-000000000012', '16590000-0000-0000-0000-000000000082', 'Revisar escopo') $$), 1, 'inicia retirada durante submissão');
select pg_sleep(0.2);
select is(extensions.dblink_is_busy('s165b'), 1, 'retirada aguarda submissão');
select extensions.dblink_exec('s165a', 'commit');
select is((select count(*)::int from extensions.dblink_get_result('s165b', false) as t(resultado jsonb)), 0, 'retirada anterior à submissão não executa');
select ok(position('revisao_obsoleta' in extensions.dblink_error_message('s165b')) > 0, 'retirada concorrente informa revisão obsoleta');
select * from extensions.dblink_get_result('s165b', false) as t(resultado jsonb);
select extensions.dblink_exec('s165b', 'rollback');
select is((select count(*)::int from pcm.rotinas_manutencao where id = '16590000-0000-0000-0000-000000000082'), 1, 'submissão preserva Rotina');
-- Retirada confirmada impede submissão com conteúdo desatualizado.
select extensions.dblink_exec('s165a', 'begin');
select extensions.dblink_exec('s165b', 'begin');
select is((resultado->>'revision')::int, 3, 'retirada inicia atualização do Plano') from extensions.dblink('s165a', $$ select pcm.sso_retirar_rotina_rascunho('16590000-0000-0000-0000-000000000123', 2, '16590000-0000-0000-0000-000000000013', '16590000-0000-0000-0000-000000000083', 'Revisar escopo') $$) as t(resultado jsonb);
select is(extensions.dblink_send_query('s165b', $$ select pcm.sso_transicionar_revisao_plano('16590000-0000-0000-0000-000000000124', 2, '16590000-0000-0000-0000-000000000013', 'submeter') $$), 1, 'inicia submissão durante retirada');
select pg_sleep(0.2);
select is(extensions.dblink_is_busy('s165b'), 1, 'submissão aguarda retirada');
select extensions.dblink_exec('s165a', 'commit');
select is((select count(*)::int from extensions.dblink_get_result('s165b', false) as t(resultado jsonb)), 0, 'submissão obsoleta não executa');
select ok(position('revisao_obsoleta' in extensions.dblink_error_message('s165b')) > 0, 'submissão concorrente informa revisão obsoleta');
select * from extensions.dblink_get_result('s165b', false) as t(resultado jsonb);
select extensions.dblink_exec('s165b', 'rollback');
select is((select estado from pcm.planos_manutencao where id = '16590000-0000-0000-0000-000000000013'), 'rascunho', 'Plano permanece em rascunho após submissão recusada');
-- Uma edição confirmada durante a espera invalida a retirada baseada na revisão anterior.
select extensions.dblink_exec('s165a', 'begin');
select extensions.dblink_exec('s165b', 'begin');
select is((resultado->>'revision')::int, 3, 'edição concorrente incrementa revisão') from extensions.dblink('s165a', $$ select pcm.sso_editar_rotina_rascunho('16590000-0000-0000-0000-000000000104', 2, '16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-000000000081', 'Rotina editada', 'sistema', '16590000-0000-0000-0000-000000000051', 'calendario', 1, 'meses', null, 0, 0, 0, null, null) $$) as t(resultado jsonb);
select is(extensions.dblink_send_query('s165b', $$ select pcm.sso_retirar_rotina_rascunho('16590000-0000-0000-0000-000000000105', 2, '16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-000000000081', 'Escopo revisto') $$), 1, 'inicia retirada com revisão concorrente');
select pg_sleep(0.2);
select is(extensions.dblink_is_busy('s165b'), 1, 'retirada espera edição');
select extensions.dblink_exec('s165a', 'commit');
select is((select count(*)::int from extensions.dblink_get_result('s165b', false) as t(resultado jsonb)), 0, 'retirada obsoleta não executa');
select ok(position('revisao_obsoleta' in extensions.dblink_error_message('s165b')) > 0, 'retirada informa conflito de revisão');
select * from extensions.dblink_get_result('s165b', false) as t(resultado jsonb);
select extensions.dblink_exec('s165b', 'rollback');
select is((select nome from pcm.rotinas_manutencao where id = '16590000-0000-0000-0000-000000000081'), 'Rotina editada', 'edição confirmada permanece e retirada não apaga Rotina');
select extensions.dblink_exec('s165a', 'begin');
select extensions.dblink_exec('s165b', 'begin');
select is((resultado->>'revision')::int, 4, 'retirada inicial incrementa revisão') from extensions.dblink('s165a', $$ select pcm.sso_retirar_rotina_rascunho('16590000-0000-0000-0000-000000000103', 3, '16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-000000000081', 'Escopo revisto') $$) as t(resultado jsonb);
select is(extensions.dblink_send_query('s165b', $$ select pcm.sso_editar_rotina_rascunho('16590000-0000-0000-0000-000000000106', 3, '16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-000000000081', 'Edição tardia', 'sistema', '16590000-0000-0000-0000-000000000051', 'calendario', 1, 'meses', null, 0, 0, 0, null, null) $$), 1, 'inicia edição enquanto retirada está aberta');
select pg_sleep(0.2);
select is(extensions.dblink_is_busy('s165b'), 1, 'edição espera retirada');
select extensions.dblink_exec('s165a', 'commit');
select is((select count(*)::int from extensions.dblink_get_result('s165b', false) as t(resultado jsonb)), 0, 'edição obsoleta não executa');
select ok(position('revisao_obsoleta' in extensions.dblink_error_message('s165b')) > 0, 'edição informa conflito de revisão');
select * from extensions.dblink_get_result('s165b', false) as t(resultado jsonb);
select extensions.dblink_exec('s165b', 'rollback');
select is((select count(*)::int from pcm.plano_comandos where request_id = '16590000-0000-0000-0000-000000000106'), 0, 'edição rejeitada não gera comando');
-- Usa outro bloqueio de transação para demonstrar retry simultâneo do pedido já confirmado.
select extensions.dblink_exec('s165a', 'begin');
select extensions.dblink_exec('s165b', 'begin');
select * from extensions.dblink('s165a', $$ select 1 from (select pg_advisory_xact_lock(hashtextextended('plano-request:16590000-0000-0000-0000-000000000103', 0))) x $$) as t(bloqueado integer);
select is(extensions.dblink_send_query('s165b', $$ select pcm.sso_retirar_rotina_rascunho('16590000-0000-0000-0000-000000000103', 3, '16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-000000000081', 'Escopo revisto') $$), 1, 'inicia retry simultâneo');
select pg_sleep(0.2);
select is(extensions.dblink_is_busy('s165b'), 1, 'retry aguarda transação original');
select extensions.dblink_exec('s165a', 'commit');
select is((resultado->>'revision')::int, 4, 'retry retorna a revisão original') from extensions.dblink_get_result('s165b') as t(resultado jsonb);
select * from extensions.dblink_get_result('s165b') as t(resultado jsonb);
select extensions.dblink_exec('s165b', 'commit');
select is((select count(*)::int from pcm.plano_comandos where request_id = '16590000-0000-0000-0000-000000000103'), 1, 'retry preserva um comando');
select is((select count(*)::int from audit.events where entity_id = '16590000-0000-0000-0000-000000000011' and action = 'rotina.rascunho_retirada'), 1, 'retry preserva uma auditoria');
select is((select count(*)::int from pcm.rotinas_manutencao where id = '16590000-0000-0000-0000-000000000081'), 0, 'Rotina do rascunho foi retirada');
select is((select revisao from pcm.planos_manutencao where id = '16590000-0000-0000-0000-000000000011'), 4, 'revisão incrementa uma vez');
select is((select count(*)::int from pcm.auvo_sync_outbox where row_id in ('16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-000000000081')), 0, 'retirada não gera envio Auvo');
select extensions.dblink_exec('s165a', $$
 reset role; set session_replication_role = replica;
 delete from audit.events where entity_id in ('16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-000000000012', '16590000-0000-0000-0000-000000000013', '16590000-0000-0000-0000-000000000081', '16590000-0000-0000-0000-000000000082', '16590000-0000-0000-0000-000000000083');
 delete from pcm.plano_comandos where cliente_id = '16590000-0000-0000-0000-00000000000a';
 delete from pcm.rotinas_manutencao where plano_id in ('16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-000000000012', '16590000-0000-0000-0000-000000000013');
 delete from pcm.plano_versoes where plano_id in ('16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-000000000012', '16590000-0000-0000-0000-000000000013');
 delete from pcm.planos_manutencao where id in ('16590000-0000-0000-0000-000000000011', '16590000-0000-0000-0000-000000000012', '16590000-0000-0000-0000-000000000013');
 delete from pcm.sistemas where id = '16590000-0000-0000-0000-000000000051';
 delete from config.sso_concessoes where usuario_id = '16590000-0000-0000-0000-000000000001' and cliente_id = '16590000-0000-0000-0000-00000000000a';
 delete from pcm.clientes where id = '16590000-0000-0000-0000-00000000000a';
 delete from config.usuarios where user_id = '16590000-0000-0000-0000-000000000001';
 delete from auth.users where id = '16590000-0000-0000-0000-000000000001';
 reset session_replication_role;
$$);
select extensions.dblink_disconnect('s165a');
select extensions.dblink_disconnect('s165b');
select * from finish();
rollback;
